var fs=require("fs");const targetDir="./";let fileslo=[];try{fs.readdirSync(targetDir,{recursive:!0,encoding:"utf8"}).forEach(file=>{file.endsWith(".html")&&fileslo.push(file)})}catch(err){console.error("\u30A8\u30E9\u30FC\u304C\u767A\u751F\u3057\u307E\u3057\u305F:",err)}for(let i=0;i<fileslo.length;i++){const data=fs.readFileSync(fileslo[i],"utf-8");/\s*<meta\s*name\s*=\s*["']robots["']\s*content\s*=\s*["'][^"']*(noindex|nofollow)[^"']*["']\s*>/i.test(data)&&!data.includes("data-pagefind-ignore")?fs.writeFileSync(fileslo[i],data.replace("<html","<html data-pagefind-ignore"),"utf-8"):console.log("\u6587\u5B57\u5217\u306F\u898B\u3064\u304B\u308A\u307E\u305B\u3093\u3067\u3057\u305F")}
